"""Build an isolated, read-only HII fingerprint collector. Never writes older outputs."""
from pathlib import Path
import hashlib,json,os,shutil,subprocess,sys,uuid
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[3];SAGE=HERE.parent
LEGACY=ROOT/'analysis/aitweaker_lock/probe_p3_kvm';SRC=HERE/'source';OUT=HERE/'build'
for part in ('pydeps','vm-pydeps','kvm-pydeps'):sys.path.insert(0,str(ROOT/'tools'/part))
import pefile,pycdlib
from pyfatfs.PyFat import PyFat
from pyfatfs.PyFatFS import PyFatFS
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def arr(b):return '{'+','.join('0x%02x'%x for x in b)+'}'
def main():
 SRC.mkdir(exist_ok=True);OUT.mkdir(exist_ok=True)
 prior=json.loads((LEGACY/'build.json').read_text());bindings=[]
 for p in (LEGACY/'source').rglob('*'):
  if not p.is_file():continue
  rel=p.relative_to(LEGACY/'source');assert sha(p)==prior['sources'][rel.as_posix()]
  dst=SRC/rel;dst.parent.mkdir(exist_ok=True,parents=True);shutil.copyfile(p,dst);bindings.append({'path':str(p),'sha256':sha(p)})
 for name in ('core.c','core.h','runtime.c','runtime.h'):shutil.copyfile(HERE/name,SRC/name)
 for name in ('password_core.h','password_crypto.c'):
  p=SAGE/'password/core'/name;shutil.copyfile(p,SRC/name);bindings.append({'path':str(p),'sha256':sha(p)})
 for name in ('memory.c','memory.h'):
  p=SAGE/'installer04/source'/name;data=p.read_text()
  expected={'memory.c':'3ef35fd0d02623e232b1855d23f17abd380755bd7c935de0edb1fb297f5d6a8b','memory.h':'54249b7f13dedabb2750decb7d0b2afd8bd6aa3742b9e45c030fecc98e477ac7'}
  assert sha(p)==expected[name]
  data=data.replace('"../../password_runtime02/source/efi.h"','"efi_min.h"').replace('->memory_map','->get_memory_map')
  (SRC/name).write_text(data);bindings.append({'path':str(p),'sha256':sha(p),'adaptation':'Only EFI header include and Boot Services field spelling changed.'})
 cat=json.loads((SAGE/'foreign_hii05/catalog.json').read_text());mods=[]
 for p in cat['packages']:
  for m in p['producer_modules']:
   if m['ffs_guid'] not in [x['ffs_guid'] for x in mods]:mods.append(m)
 mods.append({'ffs_guid':'b1da0adf-4f77-4070-a88e-bffe1c60529a','module_name':'AMITSE','path':str(SAGE/'navigation/modules/AMITSE.efi'),'sha256':'43f80bf738e0b1101431b7319a8a9c0060655e708f22f5b6379620aee862e6fe'})
 profile_text=[];profiles=[]
 for m in mods:
  path=ROOT/m['path'];assert sha(path)==m['sha256'];p=pefile.PE(str(path));mapped=p.get_memory_mapped_image();t=next(s for s in p.sections if s.Name.rstrip(b'\0')==b'.text');rel=p.OPTIONAL_HEADER.DATA_DIRECTORY[5]
  fixes=sorted([(e.rva,e.type,int.from_bytes(mapped[e.rva:e.rva+8],'little')) for b in getattr(p,'DIRECTORY_ENTRY_BASERELOC',[]) for e in b.entries if e.type and t.VirtualAddress<=e.rva<t.VirtualAddress+t.Misc_VirtualSize]);assert len(fixes)<=8 and all(x[1]==10 for x in fixes)
  tsha=hashlib.sha256(mapped[t.VirtualAddress:t.VirtualAddress+t.Misc_VirtualSize]).digest();rsha=hashlib.sha256(mapped[rel.VirtualAddress:rel.VirtualAddress+rel.Size]).digest()
  profile_text.append('{'+arr(uuid.UUID(m['ffs_guid']).bytes_le)+',"'+m['module_name']+'",'+str(p.OPTIONAL_HEADER.ImageBase)+'ULL,'+','.join(str(x) for x in (p.OPTIONAL_HEADER.SizeOfImage,p.OPTIONAL_HEADER.AddressOfEntryPoint,t.VirtualAddress,t.Misc_VirtualSize,rel.VirtualAddress,rel.Size,len(fixes)))+','+arr(tsha)+','+arr(rsha)+',{'+(','.join('{%d,%d,%dULL}'%x for x in fixes) if fixes else '{0,0,0}')+'}}')
  profiles.append({'name':m['module_name'],'guid':m['ffs_guid'],'path':str(path),'sha256':sha(path),'text_rva':t.VirtualAddress,'text_size':t.Misc_VirtualSize,'text_sha256':tsha.hex(),'reloc_rva':rel.VirtualAddress,'reloc_size':rel.Size,'reloc_sha256':rsha.hex(),'text_fixups':fixes})
 (SRC/'known_profiles.h').write_text('/* Exact original W890 0603 profiles. Generated by build.py. */\nstatic const H6_PROFILE h6_profiles[]={\n'+',\n'.join(profile_text)+'\n};\n')
 (OUT/'profiles.json').write_text(json.dumps(profiles,indent=2)+'\n')
 p=SRC/'probe.c';s=p.read_text()
 s=s.replace('#include "kvm.h"','#include "kvm.h"\n#include "runtime.h"')
 s=s.replace('if(!p)return 0;','if(!p)return 0;',1)
 s=s.replace('uint16_t n=(uint16_t)(p[pos+2]|((uint16_t)p[pos+3]<<8));','if(!h6_range(p+pos,4))return 0;\n        uint16_t n=(uint16_t)(p[pos+2]|((uint16_t)p[pos+3]<<8));')
 s=s.replace('if(n<4 || n>1024-pos || p[pos]==0x7f)return 0;','if(n<4 || n>1024-pos || !h6_range(p+pos,n) || p[pos]==0x7f)return 0;')
 s=s.replace('if(FAILED(st->bs->handle_protocol(h,&loaded_guid,(void **)&li)))return 0;','if(!h6_refresh()||!h6_code(st->bs->handle_protocol)){h6_loaded_bad(h,"SERVICE_RANGE");return 0;}\n    ES e=st->bs->handle_protocol(h,&loaded_guid,(void **)&li);\n    if(e){h6_loaded_bad(h,"SERVICE_STATUS");return 0;}\n    if(!h6_refresh()||!h6_range(li,sizeof(*li))){h6_loaded_bad(h,"POINTER_RANGE");return 0;}')
 start=s.index('static void owner(');end=s.index('static void inspect_images',start)
 s=s[:start]+'''static void owner(const char *label,void *fn) {
    HANDLE handle=0;LOADED *found=0;unsigned matches=0;
    if(fn&&h6_code(fn))for(UN k=0;k<image_count;k++){
        LOADED *li=loaded(images[k]);if(!li||!li->image_base)continue;
        UN addr=(UN)fn,base=(UN)li->image_base;
        if(addr>=base&&addr-base<li->image_size){handle=images[k];found=li;matches++;}
    }
    if(matches!=1){emit(label);emit(" OWNER_UNKNOWN\\r\\n");warnings++;return;}
    GUID g;int has=fv_guid(found,&g);h6_module(handle,found,has?&g:0);
    emit(label);emit(" ");if(has)guid_text(&g);else emit("NON_FV_IMAGE");
    emit(" I=0x");hex((UN)handle,16);emit(" RVA=0x");hex((UN)fn-(UN)found->image_base,8);emit("\\r\\n");
}
''' +s[end:]
 s=s.replace('if(FAILED(e)||!images||!image_count||image_count>4096)', 'if(FAILED(e)||!images||!image_count||image_count>4096||!h6_refresh()||!h6_range(images,image_count*sizeof(HANDLE)))')
 s=s.replace('if(!li || !fv_guid(li,&g))continue;','if(!li || !fv_guid(li,&g))continue;\n        if(h6_known(&g))h6_module(images[k],li,&g);')
 s=s.replace('if(!probe_image(li->image_base,(size_t)li->image_size,&info))','if(!h6_range(li->image_base,(size_t)li->image_size)||!probe_image(li->image_base,(size_t)li->image_size,&info))')
 s=s.replace('if(!FAILED(e)&&browser) {','if(!FAILED(e)&&browser&&h6_refresh()&&h6_range(browser,sizeof(*browser))) {')
 s=s.replace('if(FAILED(e)||!hii) {','if(FAILED(e)||!hii||!h6_refresh()||!h6_range(hii,sizeof(*hii))) {')
 s=s.replace('if(!hii->list||!hii->export_list||!hii->get_driver)', 'if(!h6_code(hii->list)||!h6_code(hii->export_list)||!h6_code(hii->get_driver))')
 s=s.replace('if(FAILED(e)||!bytes||bytes>capacity||bytes%sizeof(HANDLE))', 'if(FAILED(e)||!bytes||bytes>capacity||bytes%sizeof(HANDLE)||!h6_refresh()||!h6_range(handles,bytes))')
 s=s.replace('if(FAILED(e)||size>cap)', 'if(FAILED(e)||size>cap||!h6_refresh()||!h6_range(buffer,size))')
 s=s.replace('hii_valid++;','hii_valid++;\n        h6_forms(handles[i],buffer,(size_t)size);')
 s=s.replace('emit("HII ");guid_text((GUID *)buffer);','emit("HII ");guid_text((GUID *)buffer);emit(" handle=0x");hex((UN)handles[i],16);')
 s=s.replace('if(!FAILED(e)&&config) {','if(!FAILED(e)&&config&&h6_refresh()&&h6_range(config,sizeof(*config))) {')
 s=s.replace('} else warning("  HII.driver",e);','} else if(e||!h6_null_driver(handles[i],(const GUID *)buffer))warning("  HII.driver",e);')
 s=s.replace('Ai Tweaker P3 KVM - collecting read-only inventory...', 'W890 HII06 - collecting read-only fingerprints...')
 s=s.replace('inspect_images();inspect_protocols();inspect_hii();','if(h6_begin(st,emit)){inspect_images();inspect_protocols();inspect_hii();}else warnings++;\n    warnings+=h6_end();')
 s=s.replace('release(buffer);\n    }','release(buffer);\n    }')
 s=s.replace('FAILED(e)','(e!=0)')
 p.write_text(s)
 zig=ROOT/'tools/zig-x86_64-windows-0.14.1/zig.exe';env=os.environ.copy();env['ZIG_GLOBAL_CACHE_DIR']=str(ROOT/'tools/zig-cache-global');env['ZIG_LOCAL_CACHE_DIR']=str(HERE/'zig-cache')
 common=[str(zig),'clang','-target','x86_64-unknown-windows-msvc','-nostdinc','-isystem',str(zig.parent/'lib/include'),'-I',str(SRC),'-I',str(SRC/'compat'),'-std=c11','-O2','-Wall','-Wextra','-Werror','-DNDEBUG','-ffreestanding','-fno-builtin','-fno-stack-protector','-mno-red-zone','-fshort-wchar'];commands=[];objects=[]
 for name in ('probe','probe_core','kvm','vendor/qrcodegen','core','runtime','memory','password_crypto'):
  obj=OUT/(Path(name).name+'.obj');cmd=common+['-c',str(SRC/(name+'.c')),'-o',str(obj)];subprocess.run(cmd,check=True,env=env);commands.append(cmd);objects.append(str(obj))
 efi=OUT/'BOOTX64.EFI';cmd=[str(zig),'lld-link','/subsystem:efi_application','/entry:efi_main','/nodefaultlib','/machine:x64','/dynamicbase','/fixed:no','/nxcompat','/timestamp:0','/map:'+str(OUT/'probe.map'),'/out:'+str(efi)]+objects
 subprocess.run(cmd,check=True,env=env);commands.append(cmd);pe=pefile.PE(str(efi));pe.OPTIONAL_HEADER.CheckSum=pe.generate_checksum();efi.write_bytes(pe.write());assert not hasattr(pe,'DIRECTORY_ENTRY_IMPORT')
 cmd=common+['-DH6_EXPORT','-c',str(SRC/'core.c'),'-o',str(OUT/'core_test.obj')];subprocess.run(cmd,check=True,env=env);commands.append(cmd)
 cmd=[str(zig),'lld-link','/dll','/noentry','/nodefaultlib','/machine:x64','/timestamp:0','/out:'+str(OUT/'core_test.dll'),str(OUT/'core_test.obj'),str(OUT/'password_crypto.obj')];subprocess.run(cmd,check=True,env=env);commands.append(cmd)
 boot=OUT/'efiboot.img';boot.write_bytes(b'');fat=PyFat();fat.mkfs(str(boot),fat_type=16,size=16*1024*1024,label='W890HII06');fat.close()
 with PyFatFS(str(boot),utc=True) as fs:fs.makedirs('/EFI/BOOT',recreate=True);fs.writebytes('/EFI/BOOT/BOOTX64.EFI',efi.read_bytes())
 iso=pycdlib.PyCdlib();iso.new(interchange_level=3,vol_ident='W890_HII06',joliet=3);iso.add_file(str(boot),iso_path='/EFIBOOT.IMG;1',joliet_path='/EFIBOOT.IMG');iso.add_eltorito('/EFIBOOT.IMG;1',bootcatfile='/BOOT.CAT;1',boot_load_size=boot.stat().st_size//512,platform_id=0xef,efi=True,media_name='noemul',bootable=True)
 for name in ('/EFI','/EFI/BOOT'):iso.add_directory(iso_path=name,joliet_path=name)
 iso.add_file(str(efi),iso_path='/EFI/BOOT/BOOTX64.EFI;1',joliet_path='/EFI/BOOT/BOOTX64.EFI');target=OUT/'W890-HII06-FINGERPRINT-NOFLASH.iso';iso.write(str(target));iso.close()
 report={'status':'BUILT_AWAITING_LOCAL_TESTS_NOT_HARDWARE_QUALIFIED','efi_sha256':sha(efi),'efi_bytes':efi.stat().st_size,'iso_sha256':sha(target),'sources':{p.relative_to(SRC).as_posix():sha(p) for p in SRC.rglob('*') if p.is_file()},'inputs':bindings,'commands':commands,'profiles':profiles}
 (OUT/'build.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({k:report[k] for k in ('status','efi_sha256','efi_bytes','iso_sha256')},indent=2))
if __name__=='__main__':main()
